-- English paper playmat photo, four missing promo cards, the Lunar New Year red envelope and the silver replacement pack. Safe to run more than once.
update promo_items set data = data || jsonb_build_object('img','https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/paper-playmat-gencon-en-item-10652.webp','inf',(data->>'inf') || $j$ Printed on thin card stock, dark blue with gold lines: a life-and-score track numbered 0 to 8 down the left edge, zones for every card type, the Riftbound and League of Legends logos, and a 2025 Riot Games copyright line. It folds into a grid of creases, as the photo shows.$j$) where id = 'item-10652' and (data->>'inf') not like '%dark blue with gold lines%';
insert into promo_items (id, r, data)
select 'item-10663', 10663, $j${"r": 10663, "id": "item-10663", "cat": "PROMO", "nm": "Yone - Blademaster", "la": "English", "ev": "To be confirmed", "se": "SFD", "ty": "Card", "cn": "116", "ra": "Promo", "do": "Body", "tg": "Champion Unit\nYone\nIonia\nDemon", "fo": true, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/yone-blademaster-en-item-10663.webp", "inf": "Promo version of Yone - Blademaster (SFD 116/221, promo stamp, artist credit in Chinese, 2026 copyright). The event it was handed out at is still to be confirmed."}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10663');
